CREATE TABLE region (r_regionkey BIGINT, r_name TEXT ENCODING DICT(8), r_comment TEXT ENCODING DICT(32));
CREATE TABLE nation (n_nationkey BIGINT, n_name TEXT ENCODING DICT(8), n_regionkey BIGINT, n_comment TEXT ENCODING DICT(32));
CREATE TABLE supplier (s_suppkey BIGINT, s_name TEXT ENCODING DICT(32), s_address TEXT ENCODING DICT(32), s_nationkey BIGINT, s_phone TEXT ENCODING DICT(32), s_acctbal DECIMAL(15,2), s_comment TEXT ENCODING DICT(32));
CREATE TABLE customer (c_custkey BIGINT, c_name TEXT ENCODING DICT(32), c_address TEXT ENCODING DICT(32), c_nationkey BIGINT, c_phone TEXT ENCODING DICT(32), c_acctbal DECIMAL(15,2), c_mktsegment TEXT ENCODING DICT(8), c_comment TEXT ENCODING DICT(32));
CREATE TABLE part (p_partkey BIGINT, p_name TEXT ENCODING DICT(32), p_mfgr TEXT ENCODING DICT(8), p_brand TEXT ENCODING DICT(8), p_type TEXT ENCODING DICT(16), p_size INTEGER, p_container TEXT ENCODING DICT(8), p_retailprice DECIMAL(15,2), p_comment TEXT ENCODING DICT(32));
CREATE TABLE partsupp (ps_partkey BIGINT, ps_suppkey BIGINT, ps_availqty INTEGER, ps_supplycost DECIMAL(15,2), ps_comment TEXT ENCODING DICT(32));
CREATE TABLE orders (o_orderkey BIGINT, o_custkey BIGINT, o_orderstatus TEXT ENCODING DICT(8), o_totalprice DECIMAL(15,2), o_orderdate DATE ENCODING DAYS(32), o_orderpriority TEXT ENCODING DICT(8), o_clerk TEXT ENCODING DICT(32), o_shippriority INTEGER, o_comment TEXT ENCODING NONE);
CREATE TABLE lineitem (l_orderkey BIGINT, l_partkey BIGINT, l_suppkey BIGINT, l_linenumber INTEGER, l_quantity DECIMAL(15,2), l_extendedprice DECIMAL(15,2), l_discount DECIMAL(15,2), l_tax DECIMAL(15,2), l_returnflag TEXT ENCODING DICT(8), l_linestatus TEXT ENCODING DICT(8), l_shipdate DATE ENCODING DAYS(32), l_commitdate DATE ENCODING DAYS(32), l_receiptdate DATE ENCODING DAYS(32), l_shipinstruct TEXT ENCODING DICT(8), l_shipmode TEXT ENCODING DICT(8), l_comment TEXT ENCODING NONE);
